import SimpleLightbox from 'simplelightbox';
import 'simplelightbox/dist/simple-lightbox.min.css';
import '@fortawesome/fontawesome-free/css/all.css';
import '@fontsource/montserrat/600.css';

let galleryEl;
let loaderTextEl;
let loaderEl;
let lightbox = new SimpleLightbox('.gallery a', {
  captionsData: 'alt',
  captionPosition: 'bottom',
  captionDelay: 250
});

function getGalleryEl() {
  if (!galleryEl) {
    galleryEl = document.querySelector('ul.gallery');
  }
  return galleryEl;
}

function getLoaderTextEl() {
  if (!loaderTextEl) {
    loaderTextEl = document.querySelector('#loaderText');
  }
  return loaderTextEl;
}

function getLoaderEl() {
  if (!loaderEl) {
    loaderEl = document.querySelector('#loader');
  }
  return loaderEl;
}

export function createGallery(images) {
  let markup = images.map(function (props) {
    let {
      webformatURL,
      largeImageURL,
      tags,
      likes,
      views,
      comments,
      downloads
    } = props;
    return `<li class="gallery-item">
      <a href="${largeImageURL}" class="gallery-link">
        <img
            class="gallery-image"
            src="${webformatURL}" 
            alt="${tags}"
        />
        <div class="image-description">
          <div><h2>Likes</h2><p>${likes}</p></div>
          <div><h2>Views</h2><p>${views}</p></div>
          <div><h2>Comments</h2><p>${comments}</p></div>
          <div><h2>Downloads</h2><p>${downloads}</p></div>
        </div>
      </a>
      </li>
    `;
  });
  if (getGalleryEl()) {
    getGalleryEl().innerHTML = markup.join('');
  }
  lightbox.refresh();
}

export function clearGallery() {
  if (getGalleryEl()) {
    getGalleryEl().innerHTML = '';
  }
}

export function showLoader() {
  if (!getLoaderEl() || !getLoaderTextEl()) {
    return;
  }
  getLoaderTextEl().innerHTML = 'Loading images, please wait...';
  getLoaderEl().classList.add('loader');
}

export function hideLoader() {
  if (!getLoaderEl() || !getLoaderTextEl()) {
    return;
  }
  getLoaderTextEl().innerHTML = null;
  getLoaderEl().classList.remove('loader');
}
